<div class="page-head"><h1>Users</h1></div>
<form class="card mini-form" method="get"><div class="field"><label for="q">Search</label><input id="q" type="search" name="q" value="<?= e($q) ?>" placeholder="Name, email or phone"></div><button class="btn">Search</button></form>
<div class="card"><div class="table-wrap"><table><thead><tr><th>User</th><th>Groups</th><th>Last sign-in</th><th>Status</th><th></th></tr></thead><tbody>
<?php foreach ($rows as $u): ?><tr><td><?= e($u['full_name']) ?><?= $u['is_super_admin'] ? ' <span class="badge badge-neutral">admin</span>' : '' ?><br><span class="muted small"><?= e($u['email']) ?> <?= e($u['phone'] ?? '') ?></span></td><td><?= (int)$u['groups_n'] ?></td><td class="nowrap"><?= e(dt($u['last_login_at'])) ?></td><td><?= badge($u['status']) ?></td>
<td><form method="post" action="/admin/users/<?= (int)$u['id'] ?>/status" data-confirm="<?= $u['status'] === 'active' ? 'Suspend this account and sign them out everywhere?' : 'Restore this account?' ?>"><?= csrf_field() ?><input type="hidden" name="status" value="<?= $u['status'] === 'active' ? 'suspended' : 'active' ?>"><button class="btn small ghost"><?= $u['status'] === 'active' ? 'Suspend' : 'Restore' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div></div>
